    const date=`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`,prev=new Date(`${date}T12:00:00`);prev.setDate(prev.getDate()-1);return {kind:'day',dateFrom:date,dateTo:date,date,label:fmt(date),previous:{dateFrom:isoDate(prev),dateTo:isoDate(prev),label:fmt(isoDate(prev))},isSingleDay:true};
