  function updateServiceDayNav(){const period=servicePeriod(),selected=period.isSingleDay?period.date:'',today=new Date(),previous=new Date(today),next=new Date(today);previous.setDate(today.getDate()-1);next.setDate(today.getDate()+1);const targets={installationServicePreviousDay:isoDate(previous),installationServiceToday:isoDate(today),installationServiceNextDay:isoDate(next)};Object.entries(targets).forEach(([id,date])=>{const btn=$(id);if(!btn)return;const active=selected===date;btn.classList.toggle('is-active',active);btn.classList.toggle('primary-btn',active);btn.classList.toggle('secondary-btn',!active);btn.setAttribute('aria-pressed',String(active))})}
