  function fillServiceDays(){const year=$('installationServiceYear'),month=$('installationServiceMonth'),el=$('installationServiceDay');if(!el)return;const y=Number(year?.value),m=Number(month?.value),current=el.value;if(!y||!m){el.innerHTML='<option value="">كل الأيام</option>';el.value='';el.disabled=true;return}const count=new Date(y,m,0).getDate();el.disabled=false;el.innerHTML='<option value="">كل الأيام</option>'+Array.from({length:count},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join('');el.value=current&&Number(current)<=count?current:''}
